n=int(input())
q=list(map(int,input().split()))
a=list(map(int,input().split()))
b=list(map(int,input().split()))
am=10**6
for i in range(n):
    if a[i]==0:
        continue
    if am>q[i]//a[i]:
        am=q[i]//a[i]

ans=0
for x in range(am + 1):
    remaining = [q[i] - x * a[i] for i in range(n)]
    bm=10**6
    for i in range(n):
        if b[i]==0:
            continue
        if bm>remaining[i]//b[i]:
            bm=remaining[i]//b[i]
    ans = max(ans, x + bm)

